INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('371bcc0e-39aa-424b-9637-5e9f434b95ce', 'Maintenance - Tenant', '12', '9 (1) (2) (3)', 'MANTENIMIENTO DEL INMUEBLE', E'- The Landlord is not responsible for maintaining, improving, or repairing the property. The Tenant waives any rights related to this.\n- The Tenant must keep the property in good condition, including doors, emergency exits, windows, plumbing, drainage, fixtures, air conditioning, interior walls, floors, and ceilings.\n- The Tenant can hire a qualified contractor at their own expense for:\n  - Inspecting, adjusting, cleaning, and repairing air conditioning and ventilation systems, including changing filters quarterly. The systems must operate continuously during the mall''s open hours.\n  - Inspecting, cleaning, and repairing grease traps at least once a month or as needed.\n  - Special extraction services as outlined in the Adaptations Manual.', E'Las Partes convienen que el Arrendador no tendrá responsabilidad alguna de mantener el Inmueble o de efectuar mejora o reparación alguna al mismo, renunciando el Arrendatario a cualquier derecho que pudiera corresponderle con motivo de lo anterior.\n\nEl Arrendatario se obliga a conservar y mantener en buen estado el Inmueble y cada parte del mismo, incluyendo sin limitación las partes interiores y exteriores de las puertas, salidas de emergencia, vidrios, instalaciones de plomería y drenaje dentro del Inmueble, accesorios, aire acondicionado; así como, paredes interiores, pisos y techos.\n\nEl Arrendatario podrá contratar, a su nombre y cargo, a un contratista calificado, que preste servicios de (a) inspección, ajuste, limpieza y reparación de equipos de aire acondicionado y ventilación, incluyendo el cambio de filtros de manera trimestral, en el entendido que las unidades de ventilación y aire acondicionado serán colocadas para operación de ventilación continua durante las horas en que el Centro Comercial esté abierto al público, situación a la que expresamente se obliga el Arrendatario, (b) inspección, limpieza y reparación de trampas de grasa, en su caso, con la periodicidad que requiera el giro del Inmueble pero al menos una vez al mes, y (c) extracción especial, en su caso, observándose lo establecido para tales efectos en el Manual de Adaptaciones.');
