INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('65b1f850-6cf0-4dc6-8d83-b488737c2685', 'Late Fees', '14', '16', 'INTERESES MORATORIOS', E'- La tasa de interés por pagos atrasados es del 2% mensual.\n- Se aplica sobre el total de la deuda no pagada a tiempo.\n- Se cobra si el pago se retrasa más de 45 días desde la fecha de vencimiento.\n- El interés se calcula mensualmente o por fracción de mes mientras dure el retraso.\n- Se aplica desde la fecha en que debió hacerse el pago hasta que se pague.', 'La tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 45 (cuarenta y cinco) días de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('65b1f850-6cf0-4dc6-8d83-b488737c2685', 'Incremento de Renta', '4', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase every 12 months from the store''s opening date or the required opening date.\n- The increase is based on the change in the National Consumer Price Index (INPC) published by INEGI.\n- The comparison is made between the INPC two months before the lease starts or the last rent adjustment and the INPC two months before the new adjustment.\n- If the increase percentage is more than 6%, the maximum increase will be capped at 6%.', 'Las Partes convienen que la Renta Mensual será incrementada cada 12 (doce) meses, contado a partir de la fecha de apertura del local o de obligación de apertura, se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica: Se tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido que si el porcentaje de incremento es mayor al 6% (seis por ciento) éste será el porcentaje máximo de incremento de la Renta Mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('65b1f850-6cf0-4dc6-8d83-b488737c2685', 'Common Area Maintenance Charges', '8', '9 A)', 'GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- Cada pago mensual se añadirá al alquiler vigente cuando sea necesario.\n- La arrendataria no puede exigir detalles sobre cómo se usan los pagos.\n- La arrendataria no puede intervenir en la administración o mantenimiento del centro comercial.\n- La arrendadora debe usar los fondos para mantener, reparar y reemplazar el centro comercial y sus elementos para que funcionen bien.', 'Cada pago mensual por este concepto será incluido sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dichos conceptos, ni podrá intervenir para determinar el tipo o las características de la administración o mantenimiento del Centro Comercial, sin embargo, la Arrendadora tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.');
